import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  surface: '#0b0b10',
};

function roundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, Color, ExtrudeGeometry, PlaneGeometry, DoubleSide } = THREE;

  const root = new Group();
  root.name = 'hub-journal-card-0-label';

  const liftGroup = new Group();
  root.add(liftGroup);

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline');
  const labelText = headline?.text ?? 'Journal';
  const fontSize = headline?.typography?.fontSize ?? 39;

  // --- card plate (extruded rounded rect, PBR machined metal) ---
  const cardW = 1.0;
  const cardH = 0.34;
  const cardDepth = 0.045;
  const shape = roundedRectShape(THREE, cardW, cardH, 0.045);
  const geo = new ExtrudeGeometry(shape, {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.008,
    bevelSegments: 2,
    curveSegments: 8,
  });
  geo.center();

  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(COLORS.ink),
    metalness: 0.45,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
    side: DoubleSide,
  });

  // subtle vertical gradient across the face via TSL for machined feel
  const gradTop = vec3(0.14, 0.14, 0.17);
  const gradBottom = vec3(0.06, 0.06, 0.07);
  cardMat.colorNode = mix(gradBottom, gradTop, smoothstep(0.0, 1.0, uv().y));

  const cardMesh = new Mesh(geo, cardMat);
  liftGroup.add(cardMesh);

  // --- accent edge strip along bottom, glows on hover/focus ---
  const edgeGeo = new PlaneGeometry(cardW * 0.86, 0.02);
  const emissiveIntensityUniform = uniform(0.35);
  const edgeMat = new MeshBasicNodeMaterial({
    transparent: true,
  });
  edgeMat.colorNode = vec3(1.0, 0.165, 0.22).mul(emissiveIntensityUniform);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, -cardH / 2 + 0.02, cardDepth / 2 + 0.002);
  liftGroup.add(edgeMesh);

  // --- rim light local to this node (accent hue) ---
  const rimLight = new THREE.PointLight(new Color(COLORS.accent), 0.7, 2.2);
  rimLight.position.set(0.4, -0.3, 0.6);
  liftGroup.add(rimLight);

  // --- contact shadow (soft radial) ---
  const shadowGeo = new PlaneGeometry(cardW * 1.4, cardH * 1.6);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const suv = uv().sub(0.5).mul(2.0);
  const dist = suv.length();
  const alpha = smoothstep(1.0, 0.15, dist).mul(0.45);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = alpha;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, 0, -0.02);
  liftGroup.add(shadowMesh);

  // --- text label ---
  const textNode = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: COLORS.paper,
    align: 'center',
  });
  textNode.position.set(0, 0, cardDepth / 2 + 0.005);
  const textScale = 0.0055;
  textNode.scale.set(textScale, textScale, textScale);
  liftGroup.add(textNode);

  // --- apply configured cinematic primitives (none listed, but loop for contract) ---
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(liftGroup, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // --- entrance: rise-in ---
  liftGroup.position.y = 0.4;
  const entranceTl = gsap.timeline();
  entranceTl.to(liftGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });

  // idle glow breathing (material property, not a transform)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(emissiveIntensityUniform, {
    value: 0.5,
    duration: 2.2,
    ease: 'sine.inOut',
  });

  let hoverTl = null;
  let pressTl = null;
  let hovered = false;

  function onPointerOver() {
    if (hovered) return;
    hovered = true;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(
      liftGroup.position,
      { z: 0.12, y: 0.03, duration: 0.3, ease: 'power2.out' },
      0
    );
    hoverTl.to(liftGroup.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(emissiveIntensityUniform, { value: 1.1, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onPointerOut() {
    hovered = false;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(
      liftGroup.position,
      { z: 0, y: 0, duration: 0.35, ease: 'power2.out' },
      0
    );
    hoverTl.to(liftGroup.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' }, 0);
    hoverTl.to(emissiveIntensityUniform, { value: 0.35, duration: 0.35, ease: 'power2.out' }, 0);
  }

  function onPointerDown() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(liftGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  }

  function onPointerUp() {
    if (pressTl) pressTl.kill();
    const target = hovered ? 1.03 : 1.0;
    pressTl = gsap.timeline();
    pressTl.to(liftGroup.scale, {
      x: target,
      y: target,
      z: target,
      duration: 0.15,
      ease: 'back.out(2)',
    });
  }

  function onClick() {
    ctx.emit('hub-journal.select', { itemId: 'hub-journal-card-0' });
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
  };

  root.userData.cleanup = () => {
    entranceTl.kill();
    idleTl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    geo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (textNode.userData?.cleanup) textNode.userData.cleanup();
    liftGroup.remove(rimLight);
  };

  return root;
}
